// Contexte d'envoi transmis par le backend après validation humaine.
const body = $input.first().json.body ?? $input.first().json;

if (!body.recipient_email) {
  throw new Error('Aucun destinataire fourni pour la review ' + body.review_id);
}
if (!body.report?.storage_key) {
  throw new Error('Aucun rapport associé à la review ' + body.review_id);
}

return [{ json: {
  review_id: body.review_id,
  client_name: body.client?.name || 'Client',
  recipient_email: body.recipient_email,
  additional_info: body.additional_info || '',
  storage_key: body.report.storage_key,
  filename: body.report.filename || 'rapport.pptx',
  bucket: 'adgi360-files',
} }];

// Corps du courriel. Adapte le texte à ta façon d'écrire aux clients.
const d = $('Préparer l\'envoi').first().json;
const mois = new Date().toLocaleDateString('fr-CA', { month: 'long', year: 'numeric' });

const html = `
<div style="font-family:Inter,Helvetica,Arial,sans-serif;color:#16181F;line-height:1.6">
  <p>Bonjour,</p>
  <p>Vous trouverez ci-joint votre rapport de performance — <strong>${mois}</strong>.</p>
  ${d.additional_info ? `<p>${d.additional_info}</p>` : ''}
  <p>Nous restons disponibles pour en discuter.</p>
  <p style="margin-top:24px">
    Bien cordialement,<br>
    <strong>L'équipe ADIGI<span style="color:#E5006F">360</span></strong><br>
    <span style="color:#6B7280;font-size:13px">Grandissons ensemble !</span>
  </p>
</div>`;

return [{
  json: { ...d, subject: `Votre rapport de performance — ${mois}`, html },
  binary: $input.first().binary,
}];

return [{ json: {
  status: 'sent',
  review_id: $('Préparer l\'envoi').first().json.review_id,
  recipient: $('Préparer l\'envoi').first().json.recipient_email,
} }];
